import { test } from 'node:test';
import assert from 'node:assert/strict';
import { criarServiceDePedidos } from './solution.mjs';

function criarRepositorioFake() {
  const salvos = [];
  return {
    salvos,
    salvar(pedido) { salvos.push(pedido); },
    listar() { return salvos; },
  };
}

test('registrarPedido aplica as regras: id sequencial e total calculado', () => {
  const repositorio = criarRepositorioFake();
  const service = criarServiceDePedidos(repositorio);
  const pedido = service.registrarPedido({ produto: 'Café', quantidade: 2, precoUnitario: 8 });
  assert.deepEqual(pedido, { id: 1, produto: 'Café', quantidade: 2, precoUnitario: 8, total: 16 });
  assert.equal(repositorio.salvos.length, 1); // o service mandou salvar no repositório
});

test('totalDeTodos soma os totais de todos os pedidos', () => {
  const service = criarServiceDePedidos(criarRepositorioFake());
  assert.equal(service.totalDeTodos(), 0); // sem pedidos
  service.registrarPedido({ produto: 'Café', quantidade: 2, precoUnitario: 8 });
  service.registrarPedido({ produto: 'Bolo', quantidade: 1, precoUnitario: 12.5 });
  assert.equal(service.totalDeTodos(), 28.5);
});

test('regras de negócio recusam pedido inválido sem salvar nada', () => {
  const repositorio = criarRepositorioFake();
  const service = criarServiceDePedidos(repositorio);
  assert.throws(() => service.registrarPedido({ produto: '', quantidade: 1, precoUnitario: 8 }));
  assert.throws(() => service.registrarPedido({ produto: 'Café', quantidade: 0, precoUnitario: 8 }));
  assert.throws(() => service.registrarPedido({ produto: 'Café', quantidade: 1, precoUnitario: -1 }));
  assert.equal(repositorio.salvos.length, 0); // nada chegou ao repositório
});

test('ids são sequenciais a partir de 1', () => {
  const service = criarServiceDePedidos(criarRepositorioFake());
  const primeiro = service.registrarPedido({ produto: 'Café', quantidade: 1, precoUnitario: 8 });
  const segundo = service.registrarPedido({ produto: 'Bolo', quantidade: 1, precoUnitario: 10 });
  assert.equal(primeiro.id, 1);
  assert.equal(segundo.id, 2);
});

solutionCode:
// O service concentra a REGRA DE NEGÓCIO; o repositório (recebido de fora) só guarda.
export function criarServiceDePedidos(repositorio) {
  let proximoId = 1;

  return {
    registrarPedido({ produto, quantidade, precoUnitario } = {}) {
      if (typeof produto !== 'string' || produto.trim() === '') {
        throw new Error('produto precisa ser um texto não vazio');
      }
      if (!Number.isInteger(quantidade) || quantidade < 1) {
        throw new Error('quantidade precisa ser um inteiro maior ou igual a 1');
      }
      if (typeof precoUnitario !== 'number' || precoUnitario < 0) {
        throw new Error('precoUnitario precisa ser um número maior ou igual a 0');
      }

      const pedido = {
        id: proximoId,
        produto,
        quantidade,
        precoUnitario,
        total: quantidade * precoUnitario, // regra de negócio: o total é calculado aqui
      };
      proximoId += 1;

      repositorio.salvar(pedido); // o service NÃO sabe onde o pedido vai morar
      return pedido;
    },

    totalDeTodos() {
      return repositorio.listar().reduce((soma, pedido) => soma + pedido.total, 0);
    },
  };
}
